  ('DAI', 'Dai', 'monetary-access-rails', 'decentralized-stablecoins', 'https://makerdao.com', ARRAY['Ethereum Mainnet (with integrations across L2s)']::text[], ARRAY[]::text[], '{"description": "DAI is a decentralized, over-collateralized stablecoin issued by the MakerDAO protocol, designed to maintain a soft peg to the U.S. dollar through onchain collateralization, liquidation mechanisms, and protocol-governed monetary policy without relying on discretionary offchain redemption.", "extras": {"Collateral Type(s)": "ETH, LSTs, tokenized RWAs, other onchain assets", "Collateralization Requirement": "Dynamic (vault-type specific minimums)", "Composable in DeFi": "High", "Decentralization Strength": "Moderate", "Decentralized Stablecoin Classification": "Over-Collateralized, Onchain-Native", "Emergency Controls": "None", "Ethereum Deployment": "Yes", "Failure Mode": "Under-collateralization, oracle failure, governance failure", "Governance Control": "MakerDAO governance (MKR holders)", "Launch Year": "2017", "Liquidation Mechanism": "Collateral auctions (keeper-based liquidation system)", "Maintaining Organization / DAO": "MakerDAO", "Mint/Burn Authority": "Permissionless (via vaults, subject to protocol rules)", "Oracle Dependency": "High (price feeds critical to vault safety)", "Peg Enforcement Mechanism": "Over-collateralization with liquidation + stability fees", "Practitioner Validation Check": "Would this asset maintain its peg or monetary logic if all offchain custodians, banks, and issuers ceased to exist? Yes (protocol continues, but peg quality may degrade depending on collateral mix)", "Practitioner’s Note": "While DAI is protocol-native, its stability and risk profile are increasingly influenced by the composition of collateral—particularly RWAs and centralized stablecoins—introducing hybrid trust dependencies that practitioners must actively monitor.", "Primary Risk Source": "Governance + Oracle + Collateral Composition", "Primary Use Case": "DeFi collateral, settlement asset, DAO treasury reserve", "Protocol Type": "DAO-governed protocol", "Reason for Inclusion": "DAI meets decentralized stablecoin criteria through protocol-enforced peg logic, onchain collateral backing, permissionless minting via vaults, and the ability to maintain monetary logic independent of offchain issuers.", "Stress Event Behavior": "Liquidation cascades; emergency shutdown as last resort", "Systemic Importance": "High", "Target Peg": "USD", "Upgradeability": "Yes"}, "source_label": "Decentralized Stablecoins"}'::jsonb),
