  ('RAI', 'Rai Reflex Index', 'monetary-access-rails', 'decentralized-stablecoins', 'https://reflexer.finance', ARRAY['Ethereum Mainnet']::text[], ARRAY[]::text[], '{"description": "RAI is a decentralized, ETH-collateralized stable asset issued by the Reflexer protocol that does not target a fiat peg. Instead, it uses an algorithmic redemption-price controller to maintain a reflexive, ETH-relative unit of account governed entirely onchain.", "extras": {"Collateral Type(s)": "ETH only", "Collateralization Requirement": "Dynamic (over-collateralized system)", "Composable in DeFi": "Medium", "Decentralization Strength": "Strong", "Decentralized Stablecoin Classification": "Non-USD / Sovereign-Style Decentralized", "Emergency Controls": "Protocol-defined safeguards (no fiat backstop)", "Ethereum Deployment": "Yes", "Failure Mode": "Controller mis-calibration, governance failure, oracle error", "Governance Control": "FLX token governance (monetary policy parameters)", "Launch Year": "2021", "Liquidation Mechanism": "Collateral auctions (similar to Maker-style liquidations)", "Maintaining Organization / DAO": "Reflexer Labs (protocol governance via FLX holders)", "Mint/Burn Authority": "Permissionless (vault-based, protocol-enforced)", "Oracle Dependency": "High (ETH price + redemption price feeds)", "Peg Enforcement Mechanism": "Algorithmic monetary policy via redemption price controller", "Practitioner Validation Check": "Would this asset maintain its peg or monetary logic if all offchain custodians, banks, and issuers ceased to exist? Yes", "Practitioner’s Note": "RAI should not be evaluated as a “USD stablecoin.” It is a sovereign crypto-native monetary experiment designed to explore reflexive monetary policy without reliance on fiat pegs, making volatility in fiat terms expected rather than pathological.", "Primary Risk Source": "Monetary Policy Design + Oracle Dependence", "Primary Use Case": "ETH-native unit of account, DeFi experimentation, monetary research", "Protocol Type": "Governed protocol (monetary policy–driven)", "Reason for Inclusion": "RAI qualifies as a decentralized stablecoin because its monetary logic is enforced purely by onchain protocol mechanisms, uses only onchain collateral, and remains functional without any offchain issuers or redemption guarantees.", "Stress Event Behavior": "Redemption price adjustment rather than hard peg defense", "Systemic Importance": "Low", "Target Peg": "ETH-relative (non-USD)", "Upgradeability": "Yes"}, "source_label": "Decentralized Stablecoins"}'::jsonb),
