atory Jurisdictions": "EU, UK, United States (state-level via partners), Israel", "Primary Use Case": "Instant card-based onboarding into crypto assets", "Primary User Segment": "Retail users via exchanges, wallets, and broker platforms", "Primary Value Flow": "Fiat → ETH / Stablecoin → Ethereum", "Reason for Inclusion": "Simplex qualifies as a Global On-Ramp because its primary value proposition is enabling fiat → Ethereum asset conversion via global card networks, acting as an access gateway rather than a trading venue.", "Regional Restrictions": "Yes (jurisdiction-specific card and compliance limits)", "Regulatory Model": "Licensed / Partner-Licensed (card-network and payment-processor model)", "Role Relative to Ethereum": "Access Gateway (Card Rail Specialist)", "Supported Crypto Assets": "ETH, major stablecoins (USDC, USDT), exchange-supported assets", "Supported Fiat Currencies": "USD, EUR, GBP, and select local currencies", "Supported Payment Methods": "Credit/Debit Cards (primary), limited bank transfer support via partners", "Systemic Importance to Ethereum Access": "Medium"}, "source_label": "Global On-Ramps"}'::jsonb)
) AS v(slug, name, sector_slug, subsector_slug, website, chains, tags, meta)
JOIN public.sectors sec ON sec.slug = v.sector_slug
JOIN public.subsectors s ON s.sector_id = sec.id AND s.slug = v.subsector_slug
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  subsector_id = EXCLUDED.subsector_id,
  website = EXCLUDED.website,
  chains = EXCLUDED.chains,
  tags = EXCLUDED.tags,
  meta = EXCLUDED.meta,
  updated_at = NOW();
